import{_ as e,o,c as t,a3 as s}from"./chunks/framework.CZBGEXos.js";const p=JSON.parse('{"title":"Documentos obligatorios DS 44","description":"","frontmatter":{},"headers":[],"relativePath":"ds44/documentos-obligatorios.md","filePath":"ds44/documentos-obligatorios.md"}'),r={name:"ds44/documentos-obligatorios.md"};function n(d,a,i,l,c,u){return o(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="documentos-obligatorios-ds-44" tabindex="-1">Documentos obligatorios DS 44 <a class="header-anchor" href="#documentos-obligatorios-ds-44" aria-label="Permalink to &quot;Documentos obligatorios DS 44&quot;">​</a></h1><p>El DS 44 exige que cada obra mantenga un conjunto de documentos <strong>vigentes y firmados</strong>. La plataforma los <strong>prepara automáticamente</strong> al crear una obra, según las características que marcaste. Cada documento queda asociado a su etapa y con su flujo de firma definido, listo para que subas el archivo y recojas las firmas.</p><h2 id="catalogo-de-documentos" tabindex="-1">Catálogo de documentos <a class="header-anchor" href="#catalogo-de-documentos" aria-label="Permalink to &quot;Catálogo de documentos&quot;">​</a></h2><p>Estos son los documentos obligatorios que la plataforma gestiona:</p><table tabindex="0"><thead><tr><th>Documento</th><th>¿Para qué sirve?</th><th>¿Cuándo?</th><th>Quién firma</th></tr></thead><tbody><tr><td><strong>Informe de Riesgos Laborales (IRL)</strong></td><td>Informa al trabajador de los riesgos de su labor</td><td>Todas las etapas</td><td>Prevencionista + Trabajador</td></tr><tr><td><strong>Política de Seguridad y Salud Ocupacional</strong></td><td>Declara el compromiso de la empresa con la seguridad</td><td>Al inicio</td><td>Administrador / Jefe de Obra</td></tr><tr><td><strong>Reglamento Interno de Orden, Higiene y Seguridad</strong></td><td>Normas internas de la empresa</td><td>Al inicio</td><td>Trabajador (recepción)</td></tr><tr><td><strong>Procedimiento de Trabajo Seguro</strong></td><td>Cómo realizar una tarea de forma segura</td><td>Durante la ejecución</td><td>Supervisor + Trabajador</td></tr><tr><td><strong>Acta de Entrega de EPP</strong></td><td>Constancia de entrega de elementos de protección personal</td><td>Todas las etapas</td><td>Trabajador + Supervisor</td></tr><tr><td><strong>Encuesta / Declaración de Salud</strong></td><td>Información de salud del trabajador al ingresar</td><td>Al ingreso</td><td>Trabajador</td></tr><tr><td><strong>Registro de Capacitación SST (Art. 16)</strong></td><td>Evidencia de capacitaciones realizadas</td><td>Todas las etapas</td><td>Relator + Asistentes</td></tr><tr><td><strong>Mapa de Riesgos de la obra</strong></td><td>Identifica los riesgos por zona de la obra</td><td>Durante la ejecución</td><td>Prevencionista</td></tr><tr><td><strong>Matriz de Riesgos (MIPER / MIPPER)</strong></td><td>Identifica peligros y evalúa riesgos por cargo</td><td>Todas (por cargo)</td><td>Prevencionista</td></tr></tbody></table><blockquote><p>💡 No tienes que recordar esta lista de memoria: al crear la obra, estos documentos aparecen solos en la pestaña <strong>DS44 — Cumplimiento</strong> de la obra, esperando que los completes.</p></blockquote><h2 id="dos-tipos-de-documentos" tabindex="-1">Dos tipos de documentos <a class="header-anchor" href="#dos-tipos-de-documentos" aria-label="Permalink to &quot;Dos tipos de documentos&quot;">​</a></h2><p>La plataforma maneja dos clases de documentos, según cómo se usan:</p><h3 id="documentos-base-de-la-obra" tabindex="-1">Documentos base de la obra <a class="header-anchor" href="#documentos-base-de-la-obra" aria-label="Permalink to &quot;Documentos base de la obra&quot;">​</a></h3><ul><li>Son los <strong>obligatorios</strong> que exige el DS 44 para la obra.</li><li>Se <strong>preparan solos</strong> al crear la obra.</li><li>Deben existir y estar firmados para cumplir la normativa.</li><li>Su avance se mide como un <strong>porcentaje completado</strong> por etapa.</li></ul><h3 id="documentos-de-uso-diario" tabindex="-1">Documentos de uso diario <a class="header-anchor" href="#documentos-de-uso-diario" aria-label="Permalink to &quot;Documentos de uso diario&quot;">​</a></h3><ul><li>Se <strong>crean y asignan</strong> a personas específicas según se necesite.</li><li>Al asignarlos, la persona recibe un aviso en su <a href="/manual/modulos/bandeja-entrada.html">Bandeja de Entrada</a> y le aparecen como <strong>pendiente</strong> en su <a href="/manual/modulos/dashboard.html">Dashboard</a>.</li><li>Requieren <strong>firma individual</strong> (con PIN o presencial).</li><li>Pueden tener <strong>fecha límite</strong>; si vence sin firmar, quedan marcados como vencidos.</li></ul><h2 id="estado-de-cada-documento" tabindex="-1">Estado de cada documento <a class="header-anchor" href="#estado-de-cada-documento" aria-label="Permalink to &quot;Estado de cada documento&quot;">​</a></h2><p>Un documento avanza así:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Borrador  →  Activo  →  Completado</span></span>
<span class="line"><span>                    ↘  Vencido (si pasa la fecha límite sin firmar)</span></span></code></pre></div><p>El cumplimiento de una etapa se calcula según cuántos documentos obligatorios están <strong>completados</strong>. Al intentar <a href="/manual/ds44/fases-obra.html">avanzar de fase</a>, la plataforma verifica que la etapa anterior esté completa.</p><div class="tip custom-block"><p class="custom-block-title">Generación asistida</p><p>La <strong>matriz de riesgos</strong> puede generarse con ayuda del <a href="/manual/modulos/asistente-ia.html">Asistente IA</a>, que propone peligros, riesgos y medidas de control por cargo a partir de la normativa. El prevencionista revisa, ajusta y firma el resultado.</p></div><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h2><p><strong>¿Tengo que crear estos documentos uno por uno?</strong> No. Se preparan automáticamente al crear la obra. Tú solo subes el archivo de cada uno y recoges las firmas.</p><p><strong>¿Qué pasa si me falta uno de estos documentos?</strong> La obra mostrará una alerta de <strong>DS44 pendientes</strong> y no podrás avanzar de etapa hasta completarlo. Así te aseguras de no dejar vacíos de cumplimiento.</p><p><strong>¿Cuál es la diferencia entre un documento base y uno diario?</strong> Los <strong>base</strong> son los obligatorios de la obra y se preparan solos. Los <strong>diarios</strong> los creas y asignas tú a personas concretas según la necesidad del día a día.</p><p><strong>¿Un documento puede vencer?</strong> Sí, los documentos de uso diario pueden tener fecha límite. Si vence sin firmar, quedan marcados como vencidos y deberás regularizarlos.</p>`,22)])])}const g=e(r,[["render",n]]);export{p as __pageData,g as default};
